-- Name: impersonation_query_cache; Type: TABLE; Schema: public; Owner: admin-rsi-metabase
--

CREATE TABLE public.impersonation_query_cache (
    id integer NOT NULL,
    input_version character varying(255) NOT NULL,
    input_engine character varying(254) NOT NULL,
    input_allow_write boolean NOT NULL,
    input_admin boolean NOT NULL,
    input_query_hash character varying(64) NOT NULL,
    input_query text NOT NULL,
    result character varying(32) NOT NULL,
    result_query text,
    result_reason character varying(64),
    created_at timestamp with time zone NOT NULL
);


ALTER TABLE public.impersonation_query_cache OWNER TO "admin-rsi-metabase";

--
-- Name: TABLE impersonation_query_cache; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON TABLE public.impersonation_query_cache IS 'Cached validation results of native query stages run on impersonated databases';


--
-- Name: COLUMN impersonation_query_cache.input_version; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.input_version IS 'Metabase version that validated the query; rows from other versions are never read';


--
-- Name: COLUMN impersonation_query_cache.input_engine; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.input_engine IS 'Driver that validated the query';


--
-- Name: COLUMN impersonation_query_cache.input_allow_write; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.input_allow_write IS 'Whether the query was validated as a write statement rather than a select';


--
-- Name: COLUMN impersonation_query_cache.input_admin; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.input_admin IS 'Whether the query was validated for an admin, who is allowed more than other users';


--
-- Name: COLUMN impersonation_query_cache.input_query_hash; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.input_query_hash IS 'SHA-256 hex of input_query, used to look the row up';


--
-- Name: COLUMN impersonation_query_cache.input_query; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.input_query IS 'Native SQL of the stage after parameter substitution';


--
-- Name: COLUMN impersonation_query_cache.result; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.result IS 'Validation outcome: valid, unparseable, unvalidatable or invalid';


--
-- Name: COLUMN impersonation_query_cache.result_query; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.result_query IS 'Validated SQL to run in place of input_query, set only when result is valid';


--
-- Name: COLUMN impersonation_query_cache.result_reason; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.result_reason IS 'Why the validator could not check the query, when it says';


--
-- Name: COLUMN impersonation_query_cache.created_at; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.impersonation_query_cache.created_at IS 'Timestamp when the result was cached';


--
-- Name: impersonation_query_cache_id_seq; Type: SEQUENCE; Schema: public; Owner: admin-rsi-metabase
--

ALTER TABLE public.impersonation_query_cache ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.impersonation_query_cache_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


