-- Name: metabot_message; Type: TABLE; Schema: public; Owner: admin-rsi-metabase
--

CREATE TABLE public.metabot_message (
    id integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    profile_id text NOT NULL,
