--
-- Name: queue_message_outbox; Type: TABLE; Schema: public; Owner: admin-rsi-metabase
--

CREATE TABLE public.queue_message_outbox (
    id bigint NOT NULL,
    queue_name character varying(254) NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    payload text NOT NULL,
    publish_attempts integer DEFAULT 0 NOT NULL,
    next_attempt_at timestamp with time zone
)
WITH (autovacuum_vacuum_scale_factor='0.0', autovacuum_vacuum_threshold='50', autovacuum_analyze_scale_factor='0.0', autovacuum_analyze_threshold='50');


ALTER TABLE public.queue_message_outbox OWNER TO "admin-rsi-metabase";

--
-- Name: TABLE queue_message_outbox; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON TABLE public.queue_message_outbox IS 'Transactional outbox for queue publishes. Rows are inserted inside the business transaction (before-commit) and handed to the queue backend after it commits, so a message is published iff the transaction that produced it commits. A recovery job republishes any rows a crash left behind.';


--
-- Name: COLUMN queue_message_outbox.queue_name; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.queue_message_outbox.queue_name IS 'The name of the queue this batch will be published to';


--
-- Name: COLUMN queue_message_outbox.created_at; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.queue_message_outbox.created_at IS 'The timestamp of when the row was written to the outbox';


--
-- Name: COLUMN queue_message_outbox.payload; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.queue_message_outbox.payload IS 'JSON-encoded payload (one stored batch)';


--
-- Name: COLUMN queue_message_outbox.publish_attempts; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.queue_message_outbox.publish_attempts IS 'Number of consecutive times the recovery sweep has failed to publish this row. Drives the exponential backoff between recovery attempts; the row is never dropped (it is retried until it publishes).';


--
-- Name: COLUMN queue_message_outbox.next_attempt_at; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.queue_message_outbox.next_attempt_at IS 'Earliest time the recovery sweep may retry this row after a failed publish (now + exponential backoff). Null until the first failure; until then the sweep gates on created_at instead.';


--
-- Name: queue_message_outbox_id_seq; Type: SEQUENCE; Schema: public; Owner: admin-rsi-metabase
--

ALTER TABLE public.queue_message_outbox ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.queue_message_outbox_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


