--
-- Name: v_databases; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_databases AS
 SELECT id AS entity_id,
    concat('database_', id) AS entity_qualified_id,
    created_at,
    updated_at,
    name,
    description,
    engine AS database_type,
    metadata_sync_schedule,
    cache_field_values_schedule,
    timezone,
    is_on_demand,
    auto_run_queries,
    cache_ttl,
    creator_id,
    dbms_version AS db_version
   FROM public.metabase_database
  WHERE (id <> 13371337);


ALTER VIEW public.v_databases OWNER TO "admin-rsi-metabase";

--
-- Name: v_fields; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_fields AS
 SELECT f.id AS entity_id,
    ('field_'::text || f.id) AS entity_qualified_id,
    f.created_at,
    f.updated_at,
    f.name,
    COALESCE(u.display_name, f.display_name) AS display_name,
        CASE
            WHEN u.description_set THEN u.description
            ELSE f.description
        END AS description,
    f.base_type,
    COALESCE(u.visibility_type, f.visibility_type) AS visibility_type,
        CASE
            WHEN u.fk_target_field_id_set THEN u.fk_target_field_id
            ELSE f.fk_target_field_id
        END AS fk_target_field_id,
    COALESCE(u.has_field_values, f.has_field_values) AS has_field_values,
    f.active,
    f.table_id
   FROM (public.metabase_field f
     LEFT JOIN public.metabase_field_user_settings u ON ((u.field_id = f.id)));


ALTER VIEW public.v_fields OWNER TO "admin-rsi-metabase";

--
-- Name: v_group_members; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_group_members AS
 SELECT permissions_group_membership.user_id,
    permissions_group.id AS group_id,
    permissions_group.name AS group_name
   FROM (public.permissions_group_membership
     LEFT JOIN public.permissions_group ON ((permissions_group_membership.group_id = permissions_group.id)))
UNION
 SELECT 0 AS user_id,
    0 AS group_id,
    'Anonymous users'::character varying AS group_name;


ALTER VIEW public.v_group_members OWNER TO "admin-rsi-metabase";

--
-- Name: v_mcp_tool_calls; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_mcp_tool_calls AS
 SELECT t.id AS tool_call_id,
    t.created_at,
    t.tool_name,
    t.status,
        CASE t.error_code
            WHEN '-32600'::integer THEN 'Invalid request'::text
            WHEN '-32601'::integer THEN 'Method not found'::text
            WHEN '-32602'::integer THEN 'Invalid params'::text
            WHEN '-32603'::integer THEN 'Internal error'::text
            WHEN '-32000'::integer THEN 'Server error'::text
            ELSE NULL::text
        END AS error_type,
    t.error_message,
    t.duration_ms,
    t.user_id,
    COALESCE((((u.first_name)::text || ' '::text) || (u.last_name)::text), (u.email)::text) AS user_display_name,
    ( SELECT pg.name
           FROM (public.permissions_group_membership pgm
             JOIN public.permissions_group pg ON ((pg.id = pgm.group_id)))
          WHERE ((pgm.user_id = t.user_id) AND (pg.id <> 1))
          ORDER BY pg.name
         LIMIT 1) AS group_name,
    t.client_name,
        CASE t.client_name
            WHEN 'claude'::text THEN 'Claude'::character varying
            WHEN 'chatgpt'::text THEN 'ChatGPT'::character varying
            WHEN 'cursor-vscode'::text THEN 'Cursor'::character varying
            WHEN 'vscode'::text THEN 'VS Code'::character varying
            WHEN 'zed'::text THEN 'Zed'::character varying
            WHEN 'other'::text THEN 'Other'::character varying
            ELSE t.client_name
        END AS client_display_name,
    t.client_version,
    t.tenant_id,
    tn.name AS tenant_name,
    t.ip_address,
    t.user_agent,
    t.sanitized_user_agent
   FROM ((public.mcp_tool_call_log t
     LEFT JOIN public.core_user u ON ((u.id = t.user_id)))
     LEFT JOIN public.tenant tn ON ((tn.id = t.tenant_id)));


ALTER VIEW public.v_mcp_tool_calls OWNER TO "admin-rsi-metabase";

--
-- Name: v_metabot_conversations; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_metabot_conversations AS
SELECT
    NULL::character varying(36) AS conversation_id,
    NULL::timestamp with time zone AS created_at,
    NULL::integer AS user_id,
    NULL::text AS title,
    NULL::text AS user_display_name,
    NULL::bigint AS message_count,
    NULL::bigint AS user_message_count,
    NULL::bigint AS assistant_message_count,
    NULL::bigint AS new_message_count,
    NULL::bigint AS total_tokens,
    NULL::bigint AS prompt_tokens,
    NULL::bigint AS completion_tokens,
    NULL::timestamp with time zone AS last_message_at,
    NULL::text AS profile_id,
    NULL::text AS profile_name,
    NULL::character varying(255) AS group_name,
    NULL::character varying(100) AS source,
    NULL::character varying AS source_name,
    NULL::character varying(45) AS ip_address,
    NULL::character varying(512) AS embedding_hostname,
    NULL::character varying(2048) AS embedding_path,
    NULL::character varying(512) AS user_agent,
    NULL::character varying(512) AS sanitized_user_agent,
    NULL::character varying(36) AS forked_from_conversation_id,
    NULL::integer AS tenant_id,
    NULL::text AS tenant_name,
    NULL::character varying(255) AS model;


ALTER VIEW public.v_metabot_conversations OWNER TO "admin-rsi-metabase";

--
-- Name: v_metabot_messages; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_metabot_messages AS
 SELECT m.id AS message_id,
    m.conversation_id,
    m.created_at,
    m.role,
    m.profile_id,
    m.total_tokens,
    COALESCE(m.user_id, c.user_id) AS user_id,
    m.slack_msg_id,
    m.channel_id
   FROM (public.metabot_message m
     JOIN public.metabot_conversation c ON (((c.id)::text = (m.conversation_id)::text)))
  WHERE (m.forked_from_message_id IS NULL);


ALTER VIEW public.v_metabot_messages OWNER TO "admin-rsi-metabase";

--
-- Name: v_query_log; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_query_log AS
 SELECT query_execution.id AS entity_id,
    query_execution.started_at,
    ((query_execution.running_time)::double precision / (1000)::double precision) AS running_time_seconds,
    query_execution.result_rows,
    query_execution.native AS is_native,
    query_execution.context AS query_source,
    query_execution.error,
    COALESCE(query_execution.executor_id, 0) AS user_id,
    query_execution.card_id,
    ('card_'::text || query_execution.card_id) AS card_qualified_id,
    query_execution.dashboard_id,
    ('dashboard_'::text || query_execution.dashboard_id) AS dashboard_qualified_id,
    query_execution.pulse_id,
    query_execution.database_id,
    ('database_'::text || query_execution.database_id) AS database_qualified_id,
    query_execution.cache_hit,
    query_execution.action_id,
    ('action_'::text || query_execution.action_id) AS action_qualified_id,
    query_execution.transform_id,
    ('transform_'::text || query_execution.transform_id) AS transform_qualified_id,
    query_execution.lens_id,
    query_execution.lens_params,
    query.query,
    query_execution.embedding_client,
    query_execution.embedding_client_identifier,
    query_execution.embedding_route,
        CASE
            WHEN ((query_execution.embedding_client)::text ~~ '%-preview'::text) THEN true
            ELSE false
        END AS is_preview,
    query_execution.embedding_sdk_version,
    query_execution.metabase_version,
    query_execution.auth_method,
    query_execution.is_sandboxed,
    query_execution.sandbox_details,
    query_execution.is_impersonated,
    query_execution.is_db_routed,
    query_execution.parameters,
    query_execution.tenant_id,
    query_execution.embedding_hostname,
    query_execution.embedding_path,
    query_execution.user_agent,
    query_execution.sanitized_user_agent,
    query_execution.ip_address
   FROM (public.query_execution
     LEFT JOIN public.query ON ((query_execution.hash = query.query_hash)));


ALTER VIEW public.v_query_log OWNER TO "admin-rsi-metabase";

--
-- Name: v_subscriptions; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_subscriptions AS
 WITH agg_recipients AS (
         SELECT pulse_channel_recipient.pulse_channel_id,
            string_agg((core_user.email)::text, ','::text) AS recipients
           FROM (public.pulse_channel_recipient
             LEFT JOIN public.core_user ON ((pulse_channel_recipient.user_id = core_user.id)))
          GROUP BY pulse_channel_recipient.pulse_channel_id
        )
 SELECT pulse.id AS entity_id,
    ('pulse_'::text || pulse.id) AS entity_qualified_id,
    pulse.created_at,
    pulse.updated_at,
    pulse.creator_id,
    pulse.archived,
    ('dashboard_'::text || pulse.dashboard_id) AS dashboard_qualified_id,
    pulse_channel.schedule_type,
    pulse_channel.schedule_day,
    pulse_channel.schedule_hour,
    pulse_channel.channel_type AS recipient_type,
    agg_recipients.recipients,
    pulse_channel.details AS recipient_external,
    pulse.parameters
   FROM ((public.pulse
     LEFT JOIN public.pulse_channel ON ((pulse.id = pulse_channel.pulse_id)))
     LEFT JOIN agg_recipients ON ((pulse_channel.id = agg_recipients.pulse_channel_id)))
  WHERE (pulse.alert_condition IS NULL);


ALTER VIEW public.v_subscriptions OWNER TO "admin-rsi-metabase";

--
-- Name: v_tables; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_tables AS
 SELECT id AS entity_id,
    ('table_'::text || id) AS entity_qualified_id,
    created_at,
    updated_at,
    name,
    display_name,
    description,
    active,
    db_id AS database_id,
    schema,
    is_upload,
    entity_type,
    visibility_type,
    estimated_row_count,
    view_count,
    owner_email,
    owner_user_id
   FROM public.metabase_table;


ALTER VIEW public.v_tables OWNER TO "admin-rsi-metabase";

--
-- Name: v_task_runs; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_task_runs AS
 SELECT id,
    run_type,
    entity_type,
    entity_id,
        CASE
            WHEN ((entity_type)::text = 'database'::text) THEN ('database_'::text || entity_id)
            WHEN ((entity_type)::text = 'card'::text) THEN ('card_'::text || entity_id)
            WHEN ((entity_type)::text = 'dashboard'::text) THEN ('dashboard_'::text || entity_id)
            ELSE (((entity_type)::text || '_'::text) || entity_id)
        END AS entity_qualified_id,
    started_at,
    ended_at,
        CASE
            WHEN (ended_at IS NOT NULL) THEN (EXTRACT(epoch FROM (ended_at - started_at)))::double precision
            ELSE NULL::double precision
        END AS duration_seconds,
    status,
    process_uuid,
    updated_at
   FROM public.task_run;


ALTER VIEW public.v_task_runs OWNER TO "admin-rsi-metabase";

--
-- Name: v_tasks; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_tasks AS
 SELECT id,
    task,
    status,
    ('database_'::text || db_id) AS database_qualified_id,
    started_at,
    ended_at,
    ((duration)::double precision / (1000)::double precision) AS duration_seconds,
    task_details AS details,
    run_id
   FROM public.task_history;


ALTER VIEW public.v_tasks OWNER TO "admin-rsi-metabase";

--
-- Name: v_tenants; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_tenants AS
 SELECT id AS tenant_id,
    ('tenant_'::text || id) AS entity_qualified_id,
    name,
    slug,
    is_active,
    attributes,
    created_at,
    updated_at,
    tenant_collection_id,
    ('collection_'::text || tenant_collection_id) AS tenant_collection_qualified_id
   FROM public.tenant;


ALTER VIEW public.v_tenants OWNER TO "admin-rsi-metabase";

--
-- Name: v_users; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_users AS
 SELECT core_user.id AS user_id,
    ('user_'::text || core_user.id) AS entity_qualified_id,
    core_user.type,
        CASE
            WHEN ((core_user.type)::text = 'api-key'::text) THEN NULL::public.citext
            ELSE core_user.email
        END AS email,
    core_user.first_name,
    core_user.last_name,
    COALESCE((((core_user.first_name)::text || ' '::text) || (core_user.last_name)::text), (core_user.first_name)::text, (core_user.last_name)::text) AS full_name,
    core_user.date_joined,
    core_user.last_login,
    core_user.updated_at,
    core_user.is_superuser AS is_admin,
    core_user.is_active,
    core_user.sso_source,
    core_user.locale,
    core_user.tenant_id,
    ('tenant_'::text || core_user.tenant_id) AS tenant_qualified_id
   FROM public.core_user
UNION
 SELECT 0 AS user_id,
    'user_0'::text AS entity_qualified_id,
    'anonymous'::character varying AS type,
    NULL::public.citext AS email,
    'External'::character varying AS first_name,
    'User'::character varying AS last_name,
    'External User'::text AS full_name,
    NULL::timestamp with time zone AS date_joined,
    NULL::timestamp with time zone AS last_login,
    NULL::timestamp with time zone AS updated_at,
    false AS is_admin,
    NULL::boolean AS is_active,
    NULL::character varying AS sso_source,
    NULL::character varying AS locale,
    NULL::integer AS tenant_id,
    NULL::text AS tenant_qualified_id;


ALTER VIEW public.v_users OWNER TO "admin-rsi-metabase";

--
-- Name: view_log; Type: TABLE; Schema: public; Owner: admin-rsi-metabase
--

CREATE TABLE public.view_log (
    id integer NOT NULL,
    user_id integer,
    model character varying(16) NOT NULL,
    model_id integer NOT NULL,
    "timestamp" timestamp with time zone NOT NULL,
    metadata text,
    has_access boolean,
    context character varying(32),
    embedding_client character varying(254),
    embedding_sdk_version character varying(254),
    auth_method character varying(32),
    tenant_id integer,
    embedding_hostname character varying(512),
    embedding_path character varying(2048),
    user_agent character varying(512),
    ip_address character varying(45),
    sanitized_user_agent character varying(512),
    embedding_route character varying(64),
    metabase_version character varying(32),
    embedding_client_identifier character varying(254)
);


ALTER TABLE public.view_log OWNER TO "admin-rsi-metabase";

--
-- Name: COLUMN view_log.has_access; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.has_access IS 'Whether the user who initiated the view had read access to the item being viewed.';


--
-- Name: COLUMN view_log.context; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.context IS 'The context of the view, can be collection, question, or dashboard. Only for cards.';


--
-- Name: COLUMN view_log.embedding_client; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_client IS 'Used by the embedding team to track SDK usage';


--
-- Name: COLUMN view_log.embedding_sdk_version; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_sdk_version IS 'Used by the embedding team to track SDK version usage';


--
-- Name: COLUMN view_log.auth_method; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.auth_method IS 'Authentication method used (e.g. jwt, saml, api-key, public, guest, etc.)';


--
-- Name: COLUMN view_log.tenant_id; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.tenant_id IS 'Tenant ID of the user who generated this view';


--
-- Name: COLUMN view_log.embedding_hostname; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_hostname IS 'Hostname from Origin header, PII';


--
-- Name: COLUMN view_log.embedding_path; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_path IS 'Path from Referer header (query params stripped), PII';


--
-- Name: COLUMN view_log.user_agent; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.user_agent IS 'User-Agent header, PII';


--
-- Name: COLUMN view_log.ip_address; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.ip_address IS 'Client IP address, PII';


--
-- Name: COLUMN view_log.sanitized_user_agent; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.sanitized_user_agent IS 'Human-friendly parsed User-Agent (e.g. Browser (Chrome/Windows)), PII';


--
-- Name: COLUMN view_log.embedding_route; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_route IS 'API route surface (e.g. public, guest-embed, metabot, agent-api)';


--
-- Name: COLUMN view_log.metabase_version; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.metabase_version IS 'Metabase server version tag at time of insert';


--
-- Name: COLUMN view_log.embedding_client_identifier; Type: COMMENT; Schema: public; Owner: admin-rsi-metabase
--

COMMENT ON COLUMN public.view_log.embedding_client_identifier IS 'Identifier of the concrete embedding client (e.g. the data-app name) from the X-Metabase-Client-Identifier header';


--
-- Name: v_view_log; Type: VIEW; Schema: public; Owner: admin-rsi-metabase
--

CREATE VIEW public.v_view_log AS
 SELECT id,
    "timestamp",
    COALESCE(user_id, 0) AS user_id,
    model AS entity_type,
    model_id AS entity_id,
    (((model)::text || '_'::text) || model_id) AS entity_qualified_id,
    embedding_client,
    embedding_client_identifier,
    embedding_route,
        CASE
            WHEN ((embedding_client)::text ~~ '%-preview'::text) THEN true
            ELSE false
        END AS is_preview,
    has_access,
    context,
    embedding_sdk_version,
    metabase_version,
    auth_method,
    tenant_id,
    embedding_hostname,
    embedding_path,
    user_agent,
    sanitized_user_agent,
    ip_address
   FROM public.view_log;


ALTER VIEW public.v_view_log OWNER TO "admin-rsi-metabase";

